insert into public.ejercicio (id,nombre_es,nombre_en,musculos_principales,musculos_secundarios,equipo,categoria,tipo_registro,imagenes,instrucciones,fuente,licencia) values
('Ankle_Circles','Círculos de tobillo','Ankle Circles',ARRAY['calves']::text[],'{}'::text[],NULL,'stretching','check',ARRAY['Ankle_Circles/0.jpg','Ankle_Circles/1.jpg']::text[],ARRAY['Use a sturdy object like a squat rack to hold yourself.','Lift the right leg in the air (just around 2 inches from the floor) and perform a circular motion with the big toe. Pretend that you are drawing a big circle with it. Tip: One circle equals 1 repetition. Breathe normally as you perform the movement.','When you are done with the right foot, then repeat with the left leg.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Barbell_Squat','Sentadilla con barra','Barbell Squat',ARRAY['quadriceps']::text[],ARRAY['calves','glutes','hamstrings','lower back']::text[],'barbell','strength','reps',ARRAY['Barbell_Squat/0.jpg','Barbell_Squat/1.jpg']::text[],ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).','Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Leg_Press','Prensa de piernas','Leg Press',ARRAY['quadriceps']::text[],ARRAY['calves','glutes','hamstrings']::text[],'machine','strength','reps',ARRAY['Leg_Press/0.jpg','Leg_Press/1.jpg']::text[],ARRAY['Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).','Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.','As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.','Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.','Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Lying_Leg_Curls','Curl femoral tumbado','Lying Leg Curls',ARRAY['hamstrings']::text[],'{}'::text[],'machine','strength','reps',ARRAY['Lying_Leg_Curls/0.jpg','Lying_Leg_Curls/1.jpg']::text[],ARRAY['Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.','Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.','As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.','As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('One-Legged_Cable_Kickback','Patada de glúteo en polea a una pierna','One-Legged Cable Kickback',ARRAY['glutes']::text[],ARRAY['hamstrings']::text[],'cable','strength','reps',ARRAY['One-Legged_Cable_Kickback/0.jpg','One-Legged_Cable_Kickback/1.jpg']::text[],ARRAY['Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle.','Face the weight stack from a distance of about two feet, grasping the steel frame for support.','While keeping your knees and hips bent slightly and your abs tight, contract your glutes to slowly "kick" the working leg back in a semicircular arc as high as it will comfortably go as you breathe out. Tip: At full extension, squeeze your glutes for a second in order to achieve a peak contraction.','Now slowly bring your working leg forward, resisting the pull of the cable until you reach the starting position.','Repeat for the recommended amount of repetitions.','Switch legs and repeat the movement for the other side.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Standing_Calf_Raises','Elevación de gemelos de pie','Standing Calf Raises',ARRAY['calves']::text[],'{}'::text[],'machine','strength','reps',ARRAY['Standing_Calf_Raises/0.jpg','Standing_Calf_Raises/1.jpg']::text[],ARRAY['Adjust the padded lever of the calf raise machine to fit your height.','Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.','Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.','Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.','Repeat for the recommended amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Standing_Gastrocnemius_Calf_Stretch','Estiramiento de gemelo de pie','Standing Gastrocnemius Calf Stretch',ARRAY['calves']::text[],ARRAY['hamstrings']::text[],NULL,'stretching','check',ARRAY['Standing_Gastrocnemius_Calf_Stretch/0.jpg','Standing_Gastrocnemius_Calf_Stretch/1.jpg']::text[],ARRAY['Place your right heel on a step with your knee extended and lean forward to grab your right toe with your right hand. Your left knee should be slightly bent and your back should be straight.','Support your weight on your left leg and place your left hand on your left thigh.','Pull your right toes toward your knee until you feel a stretch in your calf.']::text[],'Free Exercise DB','Unlicense (dominio público)')
